@@ -0,0 +1,30 @@
+// Sites (kitchens). Every location belongs to one site, and a batch belongs
+// to the site of its location. Items, suppliers, recipes and dishes are
+// shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a caller does not name one. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in file order. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and belongs to the site. */
+export function locationInSite(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && l.site === site);
+}
+
+/** The batches kept at a site's locations. */
+export function siteBatches(store, site) {
+  const here = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  return store.data.batches.filter((b) => here.has(b.location));
+}
